shellCommands.command:
rm -rf dist && cat > .ssr-check.tsx <<'EOF'
import { renderToString } from 'react-dom/server';
import { ThemeProvider } from '@gravity-ui/uikit';
import { App } from './src/App';

const html = renderToString(<ThemeProvider theme="light"><App /></ThemeProvider>);
const count = (re: RegExp) => (html.match(re) || []).length;
console.log('bytes', html.length);
console.log('rows', count(/<tr[^>]*class="g-table__row/g));
console.log('checkboxes', count(/g-table__selection-checkbox/g));
console.log('sortable headers', count(/g-table__sort[ "]/g));
console.log('pagination', count(/g-pagination/g) > 0);
console.log('has names', html.includes('Имя') && html.includes('Оклад'));
console.log('range label', (html.match(/1–10 из 57/) || [])[0]);
EOF
npx vite-node .ssr-check.tsx 2>&1 | tail -15; rm -f .ssr-check.tsx; git status --short

cat > .ssr-check.tsx <<'EOF'
import { renderToString } from 'react-dom/server';
import { ThemeProvider } from '@gravity-ui/uikit';
import { App } from './src/App';

const html = renderToString(<ThemeProvider theme="light"><App /></ThemeProvider>);
const count = (re: RegExp) => (html.match(re) || []).length;
console.log('bytes', html.length);
console.log('body rows', count(/<tr class="g-table__row/g));
console.log('checkboxes', count(/g-table__selection-checkbox/g));
console.log('sortable headers', count(/class="g-table__sort[ "]/g));
console.log('pagination', count(/class="g-pagination[ "]/g) > 0);
console.log('page buttons', count(/g-pagination__page/g));
console.log('has headers', html.includes('Имя') && html.includes('Оклад') && html.includes('Дата найма'));
console.log('range label', (html.match(/1–10 из 57/) || ['MISSING'])[0]);
console.log('sort active (name asc)', count(/g-table__sort_active/g));
EOF
npx vite-node --options.deps.inline '@gravity-ui/uikit' .ssr-check.tsx 2>&1 | tail -15; rm -f .ssr-check.tsx
